"""Load DATABRICKS_HOST/TOKEN from the harness secrets file into os.environ without printing."""

import json
import os
import re
import shlex
import urllib.request

_PATH = os.path.expanduser("~/Coding/Python/DataQ-harness/secrets.sh")


def load():
    with open(_PATH) as f:
        for line in f:
            m = re.match(r"\s*(?:export\s+)?(DATABRICKS_HOST|DATABRICKS_TOKEN)=(.*)$", line)
            if not m:
                continue
            raw = m.group(2).strip()
            if "$(" in raw or "`" in raw:
                raise SystemExit(f"{m.group(1)} is dynamic; cannot parse")
            os.environ[m.group(1)] = shlex.split(raw)[0] if raw else ""
    for k in ("DATABRICKS_HOST", "DATABRICKS_TOKEN"):
        if not os.environ.get(k):
            raise SystemExit(f"{k} missing")


def call(method, path, body=None):
    load()
    req = urllib.request.Request(
        os.environ["DATABRICKS_HOST"].rstrip("/") + path,
        method=method,
        data=json.dumps(body).encode() if body is not None else None,
        headers={
            "Authorization": "Bearer " + os.environ["DATABRICKS_TOKEN"],
            "Content-Type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=120) as r:
            return json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        return {"_http_error": e.code, "_body": e.read().decode()[:500]}

