import sys
import time

from dbxenv import call

WH = "b6403b6e3734f0ce"


def sql(stmt):
    r = call(
        "POST",
        "/api/2.0/sql/statements",
        {"warehouse_id": WH, "statement": stmt, "wait_timeout": "50s"},
    )
    while r.get("status", {}).get("state") in ("PENDING", "RUNNING"):
        time.sleep(3)
        r = call("GET", f"/api/2.0/sql/statements/{r['statement_id']}")
    st = r.get("status", {})
    if st.get("state") != "SUCCEEDED":
        return f"ERR {st.get('state')} {st.get('error', {}).get('message', '')[:400]} {r.get('_body', '')}"
    return r.get("result", {}).get("data_array")


if __name__ == "__main__":
    for s in sys.argv[1:]:
        print(">", s[:120])
        print(sql(s))

